for pattern in ['exception_only_nomarker*/final/eval_results.json', 'exception_only_seed*/final/eval_results*.json', 'nomarker*/final/eval_results.json', 'fewshot*/eval_results*.json', 'zeroshot*/eval_results*.json']:
    for f in sorted(glob.glob(pattern)):
        try:
            with open(f) as fp:
                d = json.load(fp)
            m = d.get('metrics', d)
            acc = m.get('accuracy', None)
            if acc is not None:
                print(f'{round(acc*100,2):>7.2f}% | {f}')
        except:
            pass
